UPDATE fact_cards SET topic_ru = 'В журнале «Муштум»', question_ru = 'В редакции какого сатирического журнала работал Гафур Гулям?', fact_ru = 'Я работал в редакции сатирического журнала «Муштум» — смехом и шуткой я критиковал недостатки жизни.' WHERE id = 1589;
