UPDATE fact_cards SET topic_ru = 'Места моего имени', question_ru = 'Что названо именем Гафура Гуляма в Ташкенте?', fact_ru = 'Моим именем названы большое издательство литературы и искусства в Ташкенте, станция метро и парк культуры. А в доме, где я жил, открыт дом-музей.' WHERE id = 1591;
